  $state: 5 as number, set => {
    $derived: $state * 2, (doubled) => {
      console.log(`The doubled value is: ${doubled}`);
    };
  };

  let number;
  $state: number, (value) => {
    number = value;
  };

  let doubled;
  $derived: number, (value) => {
    doubled = value;
  };

  function increment() {
    $state += 1;
  }
</script>

<div>
  <p data-testid="number-value">Number: {number}</p>
  <p data-testid="doubled-value">Doubled: {doubled}</p>
  <button data-testid="increment-button" on:click={increment}>Increment</button>
</div>
