<script>
  import { $state, $inspect, $effect } from '$qwik-core';

  $state('text', 'Hello world');

  $inspect($state('text'));

  $inspect($state('text')).with((text) => {
    console.log('Text changed:', text);
  });

  $effect(
    () => {
      $inspect($state('text')).trace();
    },
    { watch: $state('text') }
  );
</script>

<div>
  <input data-testid="text-input" type="text" bind:value={$state('text')} />
  <p data-testid="text-value">Current text: "{$state('text')}"</p>
  <p data-testid="char-count">Character count: {$state('text').length}</p>
</div>
