<script>
  $state = {
    count: $props.count ?? 0,
  };

  function increment() {
    $state.count += 1;
  }
</script>

<div>
  <h1 data-testid="name-display">Hello, {$props.name ?? 'World'}</h1>
  <p data-testid="count-display">Count: {$state.count}</p>
  <button data-testid="increment-button" on:click={increment}>Increment</button>

  {#if $props.showDetails ?? false}
    <div data-testid="details">
      <p>Name is {$props.name ?? 'World'}</p>
      <p>Count is {$state.count}</p>
      <p>ShowDetails is {($props.showDetails ?? false).toString()}</p>
    </div>
  {/if}
</div>
